#Requires -Version 5.1

<#
.SYNOPSIS
    Checks the Azure networking an AVD deployment depends on: virtual networks, DNS, peering, routing and latency. Can fix some issues, only when asked.

.DESCRIPTION
    Checks the network side of an Azure Virtual Desktop deployment in one subscription:
    virtual networks and subnets, network security group rules AVD needs, DNS and
    private DNS zones, virtual network peering, routes that would block AVD traffic,
    and latency to Azure. It can also report what the chosen session host join type
    and profile storage authentication require of the network.

    By default it is read-only. Issues it knows how to fix (a missing NSG rule, a
    missing private DNS zone, a peering problem, a blocking route) are listed at the
    end, and are only changed when -EnableRemediation is given.

    The script runs in English, Spanish or Portuguese. Without -Language it asks.

    Every run signs in afresh. Before signing in it clears the Azure PowerShell sign-in
    saved on this computer (Clear-AzContext), so other Azure PowerShell sessions will
    need to sign in again afterwards. Interactive runs offer browser, device code and
    other sign-in methods; -NonInteractive uses browser sign-in.

    Missing Az modules are staged in a temporary folder for the run and removed
    afterwards. An Excel report is written beside the script.

.PARAMETER Language
    English, Spanish or Portuguese (en-US, es-VE and pt-BR are also accepted).
    Without it the script asks, or uses English with -NonInteractive.

.PARAMETER SubscriptionId
    The subscription to check. Without it the script lists your subscriptions to choose from.
    With -NonInteractive and no -SubscriptionId it continues only if the account has exactly one subscription.

.PARAMETER SkipDNSValidation
    Skips the DNS and private DNS zone checks.

.PARAMETER SkipPeeringValidation
    Skips the virtual network peering checks.

.PARAMETER SkipLatencyTest
    Skips the latency test.

.PARAMETER SessionHostJoinType
    How the session hosts will join a directory: MicrosoftEntraID, ActiveDirectoryDomainServices,
    or NotAssessed. Adds what that choice requires of the network. Without it the script
    asks, or uses NotAssessed with -NonInteractive.

.PARAMETER ProfileStorageAuthentication
    How FSLogix profile storage on Azure Files authenticates users: MicrosoftEntraKerberos,
    ActiveDirectoryDomainServices, or NotAssessed. Adds what that choice requires of the
    network. Without it the script asks, or uses NotAssessed with -NonInteractive.

.PARAMETER ReportPath
    A name for the Excel report. Only the file name is used: the report is always written beside the script.

.PARAMETER NonInteractive
    Runs without menus or prompts, for automation. Remediation is skipped unless both -EnableRemediation and -AutoFixAll are given.

.PARAMETER EnableRemediation
    After the checks, offers to fix the issues it can: all of them, or one at a time with a prompt for each.
    This changes Azure resources. Without it the script only reports them.

.PARAMETER AutoFixAll
    With -EnableRemediation, fixes every issue it can without asking. This changes Azure
    resources with no prompt: review a read-only run first.

.EXAMPLE
    .\02_AVD_Validate_Network_Configuration.ps1

    Asks for the language, sign-in, subscription and identity choices, then checks the network. Read-only.

.EXAMPLE
    .\02_AVD_Validate_Network_Configuration.ps1 -Language English -SubscriptionId "YOUR-SUBSCRIPTION-ID" -SessionHostJoinType MicrosoftEntraID -ProfileStorageAuthentication MicrosoftEntraKerberos -NonInteractive

    Unattended, read-only run for Entra-joined session hosts with Entra Kerberos profile storage.

.EXAMPLE
    .\02_AVD_Validate_Network_Configuration.ps1 -SubscriptionId "YOUR-SUBSCRIPTION-ID" -EnableRemediation

    Checks the network, then offers to fix what it found, asking before each change.
#>
[CmdletBinding(SupportsShouldProcess = $false)]
param(
    [ValidateSet('English', 'Spanish', 'Portuguese', 'en-US', 'es-VE', 'pt-BR')]
    [string]$Language,
    [string]$SubscriptionId,
    [switch]$SkipDNSValidation,
    [switch]$SkipPeeringValidation,
    [switch]$SkipLatencyTest,
    [string]$SessionHostJoinType,
    [string]$ProfileStorageAuthentication,
    [string]$ReportPath,
    [switch]$NonInteractive,
    [switch]$EnableRemediation,
    [switch]$AutoFixAll
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
try {
    [Console]::InputEncoding = New-Object Text.UTF8Encoding($false)
    [Console]::OutputEncoding = New-Object Text.UTF8Encoding($false)
    $OutputEncoding = [Console]::OutputEncoding
} catch {
    Write-Verbose "Could not set UTF-8 console encoding: $($_.Exception.Message)"
}

# Embedded source hashes: English=CBD3CBDEAC1EC0ECF95629E26F0205DE51EEAABC1FE8B33533250038B3413C65; Spanish=5F5991D6DFCFC886B5FA772448EC767CDFAF5718CFDD802D8A3A7350180FABA9; Portuguese=87D767801799D1F5CCCFB43C0E024FC5B6D103BDD54A3EB564B5AAB33D6E6CD7
$embeddedPayloads = @{
    English = ''
    Spanish = ''
    Portuguese = ''
}

function Expand-EmbeddedScript {
    param([Parameter(Mandatory = $true)][string]$Payload)
    $compressed = [Convert]::FromBase64String($Payload)
    $inputStream = New-Object IO.MemoryStream(,$compressed)
    $gzip = New-Object IO.Compression.GZipStream($inputStream, [IO.Compression.CompressionMode]::Decompress)
    $reader = New-Object IO.StreamReader($gzip, [Text.Encoding]::UTF8)
    try { $reader.ReadToEnd() } finally { $reader.Dispose(); $gzip.Dispose(); $inputStream.Dispose() }
}

if (-not $Language) {
    if ($NonInteractive) {
        $Language = 'English'
    } else {
        do {
            Write-Host ''
            Write-Host 'Select language / Seleccione el idioma / Selecione o idioma' -ForegroundColor Cyan
            Write-Host '  1. English'
            Write-Host ('  2. Espa{0}ol' -f [char]0x00F1)
            Write-Host ('  3. Portugu{0}s' -f [char]0x00EA)
            $languageChoice = Read-Host ('Choice / Opci{0}n / Op{1}{2}o [1]' -f [char]0x00F3, [char]0x00E7, [char]0x00E3)
            if ([string]::IsNullOrWhiteSpace($languageChoice)) { $languageChoice = '1' }
        } until ($languageChoice -in @('1', '2', '3'))
        $Language = @{'1' = 'English'; '2' = 'Spanish'; '3' = 'Portuguese'}[$languageChoice]
    }
}
$normalizedLanguage = if ($Language -in @('Spanish', 'es-VE')) { 'Spanish' } elseif ($Language -in @('Portuguese', 'pt-BR')) { 'Portuguese' } else { 'English' }

$forwardParameters = @{}
foreach ($parameterName in $PSBoundParameters.Keys) {
    if ($parameterName -ne 'Language') { $forwardParameters[$parameterName] = $PSBoundParameters[$parameterName] }
}
$validSessionHostJoinTypes = @('MicrosoftEntraID', 'ActiveDirectoryDomainServices', 'NotAssessed')
if ($PSBoundParameters.ContainsKey('SessionHostJoinType') -and $SessionHostJoinType -notin $validSessionHostJoinTypes) {
    throw "SessionHostJoinType must be one of: $($validSessionHostJoinTypes -join ', ')."
}
$validProfileStorageAuthentications = @('MicrosoftEntraKerberos', 'ActiveDirectoryDomainServices', 'NotAssessed')
if ($PSBoundParameters.ContainsKey('ProfileStorageAuthentication') -and $ProfileStorageAuthentication -notin $validProfileStorageAuthentications) {
    throw "ProfileStorageAuthentication must be one of: $($validProfileStorageAuthentications -join ', ')."
}
if (-not $ReportPath) {
    $forwardParameters.ReportPath = Join-Path $PSScriptRoot ("02_AVD_Validate_Network_Configuration_Launcher_{0}.xlsx" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
}

# The engine runs in this PowerShell session, so the script behaves the same in Windows
# PowerShell 5.1, PowerShell 7 and PowerShell ISE. For the run it works from the script's
# folder, with its own temporary folder; the folder, TEMP and the module path are restored when it finishes, whether it passes or fails.
# Modules an earlier run loaded stay locked until its window closes, so that run could not
# delete its temporary folder. Delete those now; a rename fails while a folder is still in use.
Get-ChildItem -Path ([IO.Path]::GetTempPath()) -Directory -Filter 'AVD02_Temp_*' -ErrorAction SilentlyContinue | ForEach-Object {
    $staleName = 'AVD02_Stale_{0}' -f [guid]::NewGuid().ToString('N')
    try { Rename-Item -LiteralPath $_.FullName -NewName $staleName -ErrorAction Stop } catch { return }
    Remove-Item -LiteralPath (Join-Path ([IO.Path]::GetTempPath()) $staleName) -Recurse -Force -ErrorAction SilentlyContinue
}
Get-ChildItem -Path ([IO.Path]::GetTempPath()) -Directory -Filter 'AVD02_Stale_*' -ErrorAction SilentlyContinue |
    ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
$engineTempPath = Join-Path ([IO.Path]::GetTempPath()) ("AVD02_Temp_{0}" -f [guid]::NewGuid().ToString('N'))
$previousEnvironment = @{
    AVD_REPORT_SCRIPT_NAME = $env:AVD_REPORT_SCRIPT_NAME
    PSModulePath = $env:PSModulePath
    TEMP = $env:TEMP
    TMP = $env:TMP
}
$previousLocation = Get-Location
try {
    New-Item -ItemType Directory -Path $engineTempPath -ErrorAction Stop | Out-Null
    $env:AVD_REPORT_SCRIPT_NAME = '02_AVD_Validate_Network_Configuration_Launcher'
    $env:TEMP = $engineTempPath
    $env:TMP = $engineTempPath
    Set-Location -LiteralPath $PSScriptRoot
    $engine = [scriptblock]::Create((Expand-EmbeddedScript -Payload $embeddedPayloads[$normalizedLanguage]))
    $global:LASTEXITCODE = 0
    & $engine @forwardParameters
} finally {
    Set-Location -LiteralPath $previousLocation.Path
    foreach ($name in $previousEnvironment.Keys) {
        $value = $previousEnvironment[$name]
        if ($null -eq $value) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue } else { Set-Item "Env:$name" $value }
    }
    # Modules the engine loaded from here stay locked until PowerShell closes; what can be removed is.
    Remove-Item -LiteralPath $engineTempPath -Recurse -Force -ErrorAction SilentlyContinue
}
